CREATE TABLE `factura` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nit_emisor` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `razon_social_emisor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `municipio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `telefono` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero_factura` int NOT NULL,
  `cuf` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `cufd` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo_sucursal` int NOT NULL,
  `direccion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo_punto_venta` int DEFAULT NULL,
  `fecha_emision` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_razon_social` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `codigo_tipo_documento_identidad` int NOT NULL,
  `numero_documento` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `complemento` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `codigo_cliente` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo_metodo_pago` int NOT NULL,
  `numero_tarjeta` int DEFAULT NULL,
  `monto_total` decimal(10,2) NOT NULL,
  `monto_total_sujeto_iva` decimal(10,2) DEFAULT NULL,
  `monto_gift_card` decimal(10,2) DEFAULT NULL,
  `descuento_adicional` int DEFAULT NULL,
  `codigo_excepcion` int DEFAULT NULL,
  `cafc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `codigo_moneda` int NOT NULL,
  `tipo_cambio` int NOT NULL,
  `monto_total_moneda` int NOT NULL,
  `leyenda` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `usuario` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigo_documento_sector` int NOT NULL,
  `id_empresa` int DEFAULT NULL,
  `id_nota_venta` int DEFAULT NULL,
  `estado` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_nota_venta_empresa` (`id_nota_venta`,`id_empresa`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `fotocopia` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `id_empresa` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=469 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `gasto` (
  `id` int NOT NULL AUTO_INCREMENT,
  `detalle` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nota` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `precio_gasto` decimal(10,2) NOT NULL DEFAULT '0.00',
  `fecha` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id_gasto_padre` int DEFAULT NULL,
  `id_empleado` int DEFAULT NULL,
  `id_tipo_gasto` int DEFAULT NULL,
  `id_usuario` int DEFAULT NULL,
  `id_caja` int NOT NULL,
  `id_empresa` int NOT NULL,
  `estado` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Procesado',
  `id_usuario_cancelo` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_gasto_id_caja` (`id_caja`)
) ENGINE=InnoDB AUTO_INCREMENT=951 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


