CREATE TABLE `sector_empresa` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_empresa` int DEFAULT NULL,
  `id_sector` int DEFAULT NULL,
  `id_modalidad` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `sessions` (
  `id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_activity` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `sucursal` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codigo` int DEFAULT NULL,
  `nombre` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `municipio` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direccion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefono` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cuis` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `codigo_punto_venta` int DEFAULT NULL,
  `id_empresa` int DEFAULT NULL,
  `fecha_registro` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `id_empresa` (`id_empresa`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `tipo_gasto` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_empresa` int DEFAULT '0',
  `nombre` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `tipo_ingreso_egreso` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detalle` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `id_empresa` int NOT NULL,
  `fecha` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `estado` int NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `id_empresa` (`id_empresa`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `tipo_producto` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_empresa` int DEFAULT '0',
  `nombre` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado` int DEFAULT '1',
  `estado_pedido` int NOT NULL DEFAULT '0',
  `id_lugar` int NOT NULL DEFAULT '0',
  `direccion_imagen` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=212 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






CREATE TABLE `transaccion_qr_bancofie` (
  `id_transaccion` bigint unsigned NOT NULL COMMENT 'idTransaccion devuelto por Banco FIE',
  `id_qr` varchar(60) DEFAULT NULL,
  `id_empresa` int DEFAULT NULL,
  `id_nota_venta` int DEFAULT NULL COMMENT 'se llena cuando la venta queda registrada',
  `id_usuario_registro` int DEFAULT NULL COMMENT 'users.id del cajero',
  `origen` varchar(20) DEFAULT 'NOTA_VENTA',
  `alias` varchar(150) DEFAULT NULL,
  `detalle_glosa` varchar(255) DEFAULT NULL,
  `moneda` varchar(5) DEFAULT 'BOB',
  `monto` decimal(10,2) DEFAULT NULL,
  `id_servicio` int DEFAULT NULL,
  `banco_destino` varchar(100) DEFAULT NULL,
  `cuenta_destino` varchar(30) DEFAULT NULL,
  `fecha_vencimiento` date DEFAULT NULL,
  `estado_pago` varchar(20) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE | PAGADO | ...',
  `cliente_ref` varchar(30) DEFAULT NULL,
  `fecha_alta` datetime DEFAULT CURRENT_TIMESTAMP,
  `fecha_pago` datetime DEFAULT NULL,
  `fecha_verificacion` datetime DEFAULT NULL,
  PRIMARY KEY (`id_transaccion`),
  KEY `idx_tqb_empresa` (`id_empresa`),
  KEY `idx_tqb_nota_venta` (`id_nota_venta`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;






CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `usuario` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `privilegio` int DEFAULT NULL,
  `permiso` int NOT NULL DEFAULT '0',
  `estado` int NOT NULL DEFAULT '1',
  `codigo_sistema` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `nit` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `token_sin` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `codigo_sucursal` int DEFAULT NULL,
  `punto_venta` int DEFAULT NULL,
  `cuis` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
